///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_list
 * @description list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_list = async function () {
    const sbmOptions = {
        id: "tx_fn_list",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_listReq",
        target: "dlt_disclsChrgList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_getApplId
 * @description get Appl Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_getApplId = async function () {
    const sbmOptions = {
        id: "tx_fn_getApplId",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_getApplIdReq",
        isProcessMsg: false
