/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @param {*} sec sec
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function (sec) {
    if (sec === 'temp') {
        // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
        let disclsChrg = $('#disclsChrg option:selected').val();
        if (disclsChrg === 'direct') {
            if (dma_hiddenStore.get("telNoTemp") !== '' && dma_hiddenStore.get("telNoTemp") != null) {
                if (scwin.fnTelNoCheck(dma_hiddenStore.get("telNoTemp"))) {
                    await $c.win.alert("연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                    return false;
                }
            }
            if (dma_hiddenStore.get("cellphoneNoTemp") !== '' && dma_hiddenStore.get("cellphoneNoTemp") != null) {
                if (scwin.fnCellPhoneCheck(dma_hiddenStore.get("cellphoneNoTemp"))) {
                    await $c.win.alert("휴대폰 형식이 틀렸습니다.\nex)010-0000-0000");
                    return false;
                }
            }
        }
        if ($c.util.getComponent('ipt_formKorNm').getValue().trim() === '' || $c.util.getComponent('ipt_formKorNm').getValue() == null) {
            await $c.win.alert("제목을 입력하세요.");
            return false;
        }
        if (($c.util.getComponent('txa_quesContn').getValue() == null ? '' : String($c.util.getComponent('txa_quesContn').getValue())) !== '' && $c.util.getComponent('txa_quesContn').getValue() != null) {
            if (scwin.calBytes($c.util.getComponent('txa_quesContn').getValue()) > 2000) {
                await $c.win.alert("상담내용은 한글 1000자 이하, 숫자/영문 2000자 이하까지만 입력이 가능합니다.");
                return false;
            }
        }
    } else {
        // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
        disclsChrg = $('#disclsChrg option:selected').val();
        if (disclsChrg === 'direct') {
            if (dma_hiddenStore.get("wrtrNmTemp") === '' || dma_hiddenStore.get("wrtrNmTemp") == null) {
                await $c.win.alert("등록자를 작성하세요.");
                return false;
            }
            if ((dma_hiddenStore.get("telNoTemp") === '' || dma_hiddenStore.get("telNoTemp") == null) && (dma_hiddenStore.get("cellphoneNoTemp") === '' || dma_hiddenStore.get("cellphoneNoTemp") == null)) {
                await $c.win.alert("연락처 또는 휴대폰을 작성하세요.");
                return false;
            }
            if (dma_hiddenStore.get("telNoTemp") !== '' && scwin.fnTelNoCheck(dma_hiddenStore.get("telNoTemp"))) {
                await $c.win.alert("연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                return false;
            }
            if (dma_hiddenStore.get("cellphoneNoTemp") !== '' && scwin.fnCellPhoneCheck(dma_hiddenStore.get("cellphoneNoTemp"))) {
                await $c.win.alert("휴대폰 형식이 틀렸습니다.\nex)010-0000-0000");
                return false;
            }
        }
        if (($c.util.getComponent('cal_disclsSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsSchdlDd').getValue())) === '' || $c.util.getComponent('cal_disclsSchdlDd').getValue() == null) {
            await $c.win.alert("공시예정일을 선택하세요.");
            return false;
        }
        if (($c.util.getComponent('ipt_formKorNm').getValue() == null ? '' : String($c.util.getComponent('ipt_formKorNm').getValue())) === '' || $c.util.getComponent('ipt_formKorNm').getValue() == null) {
            await $c.win.alert("제목을 입력하세요.");
            return false;
        }
        if (($c.util.getComponent('txa_quesContn').getValue() == null ? '' : String($c.util.getComponent('txa_quesContn').getValue())) === '' || $c.util.getComponent('txa_quesContn').getValue() == null) {
            await $c.win.alert("상담내용을 입력하세요.");
            return false;
        }
        if (scwin.calBytes($c.util.getComponent('txa_quesContn').getValue()) > 2000) {
            await $c.win.alert("상담내용은 한글 1000자 이하, 숫자/영문 2000자 이하까지만 입력이 가능합니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name fnTelNoCheck
 * @description fn Tel No Check 처리
 * @param {*} ipt_telNo ipt_telNo
 * @returns {void}
 * @hidden N
 */
scwin.fnTelNoCheck = function (ipt_telNo) {
    const regTelNo = /^(0[2-8][0-5]?)-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
    if (!regTelNo.test(ipt_telNo)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnCellPhoneCheck
 * @description fn Cell Phone Check 처리
 * @param {*} cellPhoneNum cellPhoneNum
 * @returns {void}
 * @hidden N
 */
scwin.fnCellPhoneCheck = function (cellPhoneNum) {
    const regPhone = /(01[0|1|6|7|8|9])[-](\d{3}|\d{4})[-](\d{4}$)/g;
    if (!regPhone.test(cellPhoneNum)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fileValidation
 * @description file Validation 처리
 * @param {*} sec sec
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileValidation = async function (sec) {
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (let i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fileTypeChk(file.eq(i).attr("value"));
            fSize += scwin.fileSizeChk($c.util.getComponent("attachFile" + (i + 1)).files[0].size);
        }
    }
    if (fNmLength > 0) {
        await $c.win.alert('파일명 길이가 80byte 초과된 파일이 ' + fNmLength + '개 있습니다.');
        return false;
    }
    if (fType > 0) {
        await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + fType + '개 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
        return false;
    }
    if (fSize > 0) {
        await $c.win.alert('첨부파일의 용량은 개당 50MB를 넘을수 없습니다.');
        return false;
    }
    return true;
};

/**
 * @method
 * @name fileTypeChk
 * @description file Type Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fileTypeChk = function (val) {
    const isFileType = ["drt", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt"];
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt === 0) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fileSizeChk
 * @description file Size Chk 처리
 * @param {*} fileSize fileSize
 * @returns {void}
 * @hidden N
 */
scwin.fileSizeChk = function (fileSize) {
    if (fileSize > (1024 * 1024 * 50)) {
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name tempRegister
 * @description temp Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tempRegister = async function () {
    if (!await scwin.validation('temp')) {
        return;
    }
    if (!await scwin.fileValidation('temp')) {
        return;
    }
    if (dma_hiddenStore.get("ipt_disclsConsultApplId") === '' || dma_hiddenStore.get("ipt_disclsConsultApplId") == null) {
