/**
 * @method
 * @name apiFileUpload
 * @description api File Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.apiFileUpload = async function () {
    let bl = false;
    let mimeError = true;
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const all_files = $('[type=file]');
    if (all_files.length > 0) {
        $.each(all_files, function(i, item) {
                // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
                const f = $(item)[0].files[0];
                if (f == null || f === '') {
                    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                    let idNum = $(item)[0].id;
                    idNum = idNum.replace('attachFile', '');
                    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
                    $('#fileDiv' + idNum).remove();
                }
        });
    } else {
        return true;
    }
    const oData = await scwin.getOtherData();
    if (oData === '' || oData == null || oData === 'undefined') {
        void('apiKey 조회에 실패');
        return bl;
    }
    const arr = oData.split('||');
    const apiUrl = scwin.urlInfo();
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const attach_files = $('[type=file]');
    let errCnt = attach_files.length;
    if (attach_files.length > 0) {
        $.each(attach_files, function(i, item) {
                const formData = new FormData();
                // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
                formData.append("attachFile", $(item)[0].files[0]);
                formData.append("integUsrId", arr[1]);
                const disclsConsultApplId = dma_hiddenStore.get("ipt_disclsConsultApplId");
                $.ajax({ url: apiUrl + "/auth/s1/disclosure/consult-apply/file-upload/" + disclsConsultApplId, type: "POST", data: formData, processData: false, contentType: false, async: false, headers: { "apiKey": arr[0] }, success: function(response) {
                            void('success : ' + response);
                            errCnt--;
                        }, error: function(request) {
                            void('error : ' + request);
                            errCnt++;
                            mimeError = false;
                        } });
        });
    }
    if (!mimeError) {
        bl = "E";
    } else {
        if (errCnt === 0) {
            bl = true;
        } else {
            bl = false;
        }
    }
    return bl;
};

/**
 * @method
 * @name fileNmLengthChk
 * @description file Nm Length Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fileNmLengthChk = function (val) {
    const fVal = val.split("\\");
    const fNm = fVal[fVal.length - 1];
    let returnVal = 0;
    if (scwin.calBytes(fNm) > 80) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} disclsConsultApplId disclsConsultApplId
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (disclsConsultApplId, seq) {
    const isDisclsConsultServiced = $c.util.getComponent('ipt_isDisclsConsultServiced').getValue();
    if (isDisclsConsultServiced === 'Y') {
        const oData = await scwin.getOtherData();
        if (oData === '' || oData == null || oData === 'undefined') {
            void('apiKey 조회에 실패');
            return;
        }
        const arr = oData.split('||');
        const apiUrl = scwin.urlInfo();
        $c.util.getComponent('hideFrame').src = apiUrl + '/auth/s1/disclosure/consult-apply/file-download/' + disclsConsultApplId + '/' + seq + '?apiKey=' + arr[0] + '&integUsrId=' + arr[1];
    } else {
        (document.fileDownForm || { elements: [] }).target = "hideFrame";
        $c.util.getComponent('dma_listReq').set('method', 'disclsConsultFileDown');
        $c.util.getComponent('dma_listReq').set('disclsConsultApplId', disclsConsultApplId);
        $c.util.getComponent('dma_listReq').set('seq', seq);
        $c.util.getComponent('dma_listReq').set('apiKey', '');
        $c.util.getComponent('dma_listReq').set('integUsrId', '');
        (document.fileDownForm || { elements: [] }).action = 'disclsConsult.do';
        await scwin.tx_fn_fileDown();
    }
};

